import{z as s,x as l,o,c as x,q as d,j as t,D as e,d as r,s as i,S as c}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"字符与 Unicode","description":"","frontmatter":{"title":"字符与 Unicode","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/char-unicode.md","filePath":"cs/char-unicode.md","lastUpdated":1791063341000}'),p={name:"cs/char-unicode.md"};function A(E,a,h,B,U,T){const n=l("Mermaid");return o(),x("div",null,[a[2]||(a[2]=d('<h1 id="字符与-unicode" tabindex="-1">字符与 Unicode <a class="header-anchor" href="#字符与-unicode" aria-label="Permalink to &quot;字符与 Unicode&quot;">​</a></h1><div class="epigraph"><p>文本不是数的另一种精度；它是一份事先编号的抽象字符表，再映射到比特串。</p><footer>—— 据 The Unicode Standard；ISO/IEC 10646；Patterson and Hennessy, Computer Organization and Design 整理</footer></div><p>上一课<a href="/cs/denormal-nan">非规格化与 NaN</a>钉死了浮点的交换位型。本课不重讲偏置指数，也不从「语言是什么」另起。缺口是：同一根比特串还可以不当数读。人读的符号、源程序、后课的报文，需要另一套编号——<strong>字符</strong>，不是更大的整数或另一种浮点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无符号、补码、754 都把 \\(\\Sigma^n\\) 解释成数值。文本要的是：有限字母表里的抽象字符，每个有一个码位，再选一种把码位写成字节的方案。<span class="marginnote">术语翻译：「码位」就是抽象字符表里的座位号（如 <code>U+4E2D</code> 是「中」的座位号）；「编码方案」是把这些座位号写成字节串的排版规则——同一个座位号，UTF-8 和 UTF-16 排出来的字节完全不同。两层各管各的事。</span>ASCII 只覆盖 128 个，把第 8 位置 0；各地方便页互不兼容。缺口因此不是「字符串等于字节数组」，而是先承认<strong>码位与编码方案是两层</strong>。</p><p>Unicode 给抽象字符码位 <code>U+0000</code>–<code>U+10FFFF</code>。UTF-8 把它变成变长字节，ASCII 作为子集嵌入。本课只钉这一层；规范化、字素簇、双向算法是边界，不展开。</p><h3 id="字节长度不是字符个数" tabindex="-1">字节长度不是字符个数 <a class="header-anchor" href="#字节长度不是字符个数" aria-label="Permalink to &quot;字节长度不是字符个数&quot;">​</a></h3><p>UTF-8 里一个码位可占 1–4 字节。按字节下标切，会切断多字节序列。后课的缓冲、文件、套接字都按字节寻址；文本层必须自己知道边界。把 <code>char</code> 当成「一个显示出来的字」，东亚字形与组合字符会立刻反例。</p><p><span class="marginnote">Unicode 码位是整数编号，但加减没有数值语义。UTF-16 在 BMP 外用代理对，宽度同样不是「一个字符」。源文件的编码必须与编译器约定，否则后课词法看到的已是错串。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>码位是 \\([0,0x10FFFF]\\) 中的整数，去掉代理区等非字符。UTF-8：前缀比特声明后续长度，续字节以 <code>10</code> 开头，既可自同步，又保持 ASCII 单字节。非法序列必须拒绝或替换，不能当拉丁字母继续译。</p>',11)),(o(),t(c,null,{default:e(()=>[i(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ABS%5B%22%E6%8A%BD%E8%B1%A1%E5%AD%97%E7%AC%A6%22%5D%20--%3E%20CP%5B%22%E7%A0%81%E4%BD%8D%22%5D%0A%20%20CP%20--%3E%20ENC%5B%22UTF-8%20%2F%20UTF-16%20%E5%AD%97%E8%8A%82%22%5D%0A%20%20ENC%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%86%B5%E4%B8%8E%E4%BF%A1%E9%81%93%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=d('<p>比较与排序不是码位序：字典序依赖 locale。本课只要求相等可以先比规范化后的码位序列；排序留给应用。数值课的位权在这里不适用：<code>U+0031</code> 与整数 \\(1\\) 只在「看起来像」时重合。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了码位，文件和网络才能声明 <code>charset</code>。后课指令立即数仍是数；字符串常量是汇编器或编译器按约定写成的字节。<span class="marginnote">数字实例：「中」的码位是 <code>U+4E2D</code>，落在第三档，UTF-8 编成 3 个字节 <code>E4 B8 AD</code>；而 <code>A</code>（<code>U+0041</code>）落在第一档，就是单字节 <code>41</code>，与 ASCII 完全一致——所以一段英文文本用 UTF-8 存，体积与老 ASCII 文件一字节不差。</span>操作系统的路径、环境变量在字节层，解释成字符要另说编码——混用 Latin-1 与 UTF-8 是经典事故，根子在本课两层被压成一层。</p><p>按码位落在哪一档，UTF-8 给出不同长度的字节排布：</p>',4)),(o(),t(c,null,{default:e(()=>[i(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20R1%5B%22U%2B0000%20%E5%88%B0%20U%2B007F%22%5D%20--%3E%20B1%5B%221%20%E5%AD%97%E8%8A%82%3A%200xxxxxxx%22%5D%0A%20%20R2%5B%22U%2B0080%20%E5%88%B0%20U%2B07FF%22%5D%20--%3E%20B2%5B%222%20%E5%AD%97%E8%8A%82%3A%20110xxxxx%2010xxxxxx%22%5D%0A%20%20R3%5B%22U%2B0800%20%E5%88%B0%20U%2BFFFF%22%5D%20--%3E%20B3%5B%223%20%E5%AD%97%E8%8A%82%3A%201110xxxx%2010xxxxxx%2010xxxxxx%22%5D%0A%20%20R4%5B%22U%2B10000%20%E5%88%B0%20U%2B10FFFF%22%5D%20--%3E%20B4%5B%224%20%E5%AD%97%E8%8A%82%3A%2011110xxx%2010xxxxxx%2010xxxxxx%2010xxxxxx%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=d('<p>控制字符（换行、NUL）是字母表里的成员，不是「没有字符」。C 串以 <code>0</code> 结尾，是约定，不是 Unicode 的定义。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲字体渲染、输入法、也不把正则与词法提前到编译课。Shannon 信息量还没有：字母表有了大小，分布还没有。纠错码也不在这里：UTF-8 的前缀能发现某些非法字节，不是汉明码。</p><p>后课默认：谈到文本，对象是 Unicode 码位加一种字节编码，默认 UTF-8；长度要说清是码位还是字节。<span class="marginnote">常见误区：初学者容易以为 <code>str.length</code> 这类调用返回「屏幕上看到的字符个数」。实际上多数语言返回码元或字节数：<code>E4 B8 AD</code> 这串长度是 3，「中」却只是 1 个字；带组合符号的「é」甚至可能由两个码位拼成。问「几个字」之前先问「按什么单位数」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>字符是编号表，不是浮点或补码的另一种读法。</li><li>码位与 UTF-8 等编码方案必须分开；字节长度 ≠ 字符个数。</li><li>ASCII 是 UTF-8 的子集；非法序列不能当数据蒙混。</li><li>出处：The Unicode Standard；ISO/IEC 10646。</li></ul>',6))])}const m=s(p,[["render",A]]);export{F as __pageData,m as default};
